BASES = {
 "MenuPlace": "MenuObj", "MenuItem": "MenuPlace", "MenuGroup": "MenuPlace", "MenuSprite": "MenuItem", "MenuPolygon": "MenuItem",
 "FontItem": "MenuItem", "MenuText": "FontItem", "PluralFontItem": "FontItem", "MenuMessage": "PluralFontItem", "MenuFont": "PluralFontItem",
 "MenuFontItalic": "MenuFont", "MenuObj": "DelayDeleteObject", "MenuWindow": "MenuObj (+ MenuObjTable @0x18, MenuPacket @0x24 as members)",
 "MenuWindowObject": "MenuObj", "MenuWindowPlain": "MenuWindowObject", "MenuWindowFrame": "MenuWindowObject", "MenuWindowFace": "MenuWindowObject",
 "MenuWindowNote": "MenuWindowObject", "MenuWindowGeneral": "MenuWindowObject", "MenuWindowCompact": "MenuWindowObject", "MenuWindowMessage": "MenuWindowObject",
 "MenuRender": "VIF1Prim (+CPolObj @0x14, MenuObjTable @0x2c)", "MenuScene": "DelayDeleteObject", "MenuCommon": "MenuScene", "MenuFieldData": "MenuScene",
 "MenuFieldStationed": "MenuFieldData", "GameOverScene": "MenuScene", "Menu": "CPolObj (+DelayDeleteObject @0x20)", "GameOver": "Menu",
 "BtlSaveSec": "SaveDataSection", "CFieldSaveData": "SaveDataSection", "SaveMenuSection": "SaveDataSection", "SaveData": "CPolObj",
 "SaveDeviceMC": "SaveDevice", "SaveDeviceHDD": "SaveDevice", "Cursor": "MenuObj", "ScrollMark": "MenuObj", "KeyWait": "MenuObj", "MenuFlare": "MenuObj",
 "MenuFrame": "MenuObj", "MenuRegister": "MenuObj", "MenuIcon": "MenuObjTable", "MenuCapture": "VIF1Prim", "dataAccess": "CPolObj", "openingMessage": "CPolObj",
 "openingBattleDemo": "CPolObj", "dispTime": "CPolObj", "dispCash": "CPolObj", "SendOnLocal": "MenuObj", "MenuTexture": "BufMemory-backed texture",
}
DESC = {
 "MenuObj": {"what": "Root of the menu widget hierarchy **and** a static holder for the toolkit's global state (`sm_*` members): `sm_menuRender` (the world layer that draws all menu windows, JP 0x00421a30), `sm_common` (the shared `COMMON/CMNMENU.DAT` scene, 0x00421600), `sm_pFieldData`/`sm_pCmdMenu` (field menu resource scenes), `sm_pFace` (`FileManeger` for face textures `MENU/FACE/FI_%03d.TEX`), `sm_pSound` (`MenuSound`), `sm_iPassTime/sm_fPassTime/sm_prevTime` (frame delta in ticks), `sm_fZero`, `sm_freeBlock`, `sm_clearRect`.",
   "flow": "`Initialize()` (0x002744b0) loads the common scene (`OrderFile(&sm_common, \"COMMON/CMNMENU.DAT\")`), creates the render layer (`Create` + `Entry(13)` = world OT layer 13) and `new SaveMenuSection`. `CreateField/ReleaseField` and `CreateCmdMenu/ReleaseCmdMenu` are reference counted (`+0x22`) loaders of the field-menu scenes (`MenuFieldStationed`, `MenuFieldData`) plus `MenuSound`/face file manager. `UpdateTimer()` computes `sm_iPassTime = GetTimer() - prev`; every widget's `Polling` uses it as the time step (ticks of the SysTool timer; the title code counts frames of 16 ticks). `AddOT/ReleaseOT` insert/remove a window in the render layer's priority-ordered `MenuObjTable`.\n\nInstance layout: a `MenuObj` is 0x18 bytes: `DelayDeleteObject` links (0,4), vptr @8, chain `next` @0xc (used by `MenuObjTable`), two per-VIF-buffer dirty byte masks @0x10/0x11 (bit0 header, bit1 env/position-in-window, bit3 rect, bit4 rgba, bit5 uv...), flags @0x12 (bit0 render, bit1 poll, bit2 in table, bit3 delay-delete, bit4 created), priority @0x14, id @0x16 (-1 anonymous).\n\nVtable (shared by all widgets): 0x08 dtor, 0x0c DelayDelete, 0x10 Polling, 0x14 Update(x,y,alpha), 0x18 Connect(packet), 0x1c Destroy, 0x20 Clear; `MenuPlace` adds 0x24 SetPosition, 0x28 SetSize, 0x2c SetAlpha, 0x30 SetColor, 0x34 SetBright, 0x38 SetOwner, 0x3c GetKeyPlace, 0x40 GetKeyRect, 0x44 AllotPacket, 0x48 GetAllotCount, 0x4c Attach, 0x50 Detach.",
   "rust": "`widget::ObjBase`, `window::MenuRoot` (render layer + window table), timer in `MenuRoot::update_timer`."},
 "MenuObjTable": {"what": "Priority-sorted singly linked list of `MenuObj`s (head @+4). Used as the render layer's window list and as every window's child-draw table. `AddPriority` inserts before the first element with a strictly larger priority (stable for equal priorities), sets flags `in-table`, marks both dirty masks 0x3f. `Trace*` helpers walk the list: `TracePolling` (objects with the poll flag), `TraceUpdate(x,y,alpha[,dirty])` (render flag + dirty for the current buffer), `TraceConnect(packet)` chains the GS packets, `TraceSetRendering`, `TraceAddUpdate`.",
   "rust": "`Window::draw` sorts `objs + attached places` by priority; `MenuRoot::draw` sorts windows."},
 "MenuPlace": {"what": "A rectangular, positionable widget that can be addressed by the cursor: owner window @0x18, grid cell (`col`,`row`) @0x1c/0x1e used by `MenuWindow::GetPlace/MovePlace`, flags @0x21 (bit1 selectable, bit2 selected, bit4 key place of a group, bit5 alpha relative to parent), label @0x22, rect (x,y,w,h as floats) @0x24, attached object @0x34 (the cursor 'back object' sprite), next sibling @0x38. `IsSelected(cursor)` is how a place becomes the cursor target (see Cursor). Default `Clear()` sets col=row=-1 and flags 0x2a.",
   "rust": "`widget::Place`."},
 "MenuItem": {"what": "A `MenuPlace` that owns a `MenuPacket` (double-buffered GS packet memory) and an RGBA tint @0x4c plus blink parameters. `Polling` implements blink (`SetBlink(period, base)`): phase advances by the frame time, alpha = 0x80 - |phase/20| - base. `SetColor/SetAlpha/SetBright` update the tint and mark the colour dirty.",
   "rust": "`widget::Widget` (color, blink)."},
 "MenuSprite": {"what": "Textured quad (GS sprite primitive). uv rectangle `(u0,v0,u1,v1)` in texels @0x54..0x5a, optional `linked` sprite @0x5c drawn with it. Packet = 6 qwords. `SetScale(f)` grows the rect symmetrically. Records: scene chunk type 6.",
   "rust": "`widget::Sprite`, `Widget::sprite_from_rec`."},
 "MenuPolygon": {"what": "Four-vertex Gouraud quad (strip order TL,BL,TR,BR) with per-vertex colour (colour 0 = item tint, 1..3 @0x74..0x7c) and optional per-vertex UV (`uv` pointer @0x80, 4x(u,v) shorts, allocated only with `Create(hasUV)`). `SetRect()` recomputes the bounding box; `SetPosition/SetSize` re-fit the vertices to the rect.",
   "rust": "`widget::Polygon`."},
 "FontItem": {"what": "Common base of text widgets: font canvas pointer @0x54, `FontItem` flags, `SetFontNumber`, `SetCSA` (colour-set / CLUT row), spacing @0x5c, shadow offsets @0x5a/0x5b. Text is rasterised by `FontDraw` (section B) into a shared canvas texture; the widget only references glyph rectangles.",
   "rust": "`gfx::TextRun`."},
 "PluralFontItem": {"what": "FontItem holding *two packet arrays* of 0x30-byte entries: per-glyph packets (colour/alpha/uv) and a second array used by `MenuMessage` for macros. `GetFontPacket(buffer)`, `SetUV(a,b)`, `SetFontColor`, `SetBright`.",
   "rust": "`message::Message` stores glyph entries directly."},
 "MenuText": {"what": "Single-line text label (scene chunk type 8): `SetMessage(char* sjis, len, mode, ...)` asks `FontDraw::OrderMessage` for glyph rects and fills 4 qword per glyph packets; text comes from the scene's type-1 text table (id in the record).",
   "rust": "`widget::Text`, `Widget::text_from_rec`."},
 "MenuMessage": {"what": "Typewriter message box. Per-glyph 0x30-byte packet entries (alpha @+0x17, width @+0xc, fade rate @+0x24) and macro entries (kind @+0x14, trigger glyph @+0x16, argument @+0x24). `Start()` is skipped if the text-speed option (MENU byte 0x274 bits 4-5) is 3 (instant). `Polling` reveals one glyph per `char_interval` ticks (slow 200 / normal 100 / fast 50, `SetDefault`), fades new glyphs in with `alpha += (rate*dt)>>24` (rate 0x83126f => 0x80 in ~16 ticks), and handles macros: 6 default, 5 set speed, 1/3/4 wait (state 10). `Return()` is the newline: cursor_x=0, cursor_y += line height + gap, line_no++. A `SendOnLocal` key icon (kind 4 only) is appended at the end ('more' marker).",
   "rust": "`message::Message` (+ tests).", "open": "- macro/escape byte encoding in the Shift-JIS stream is decoded by `FontDraw::Order(MenuMessage*, char*)` (section B)"},
 "MenuFont": {"what": "Large-glyph/bitmap font item (chunk type 10) created by `CreateFont(fontIndex, count, mode)`; used for number/effect fonts built from an image (`MenuFont::sm_data`, `MenuFontItalic::sm_data`).", "rust": "not ported (needs FontDraw/Font tables from section B)."},
 "MenuFontItalic": {"what": "Italic variant created from an image blob by name (`CreateItalic(char*)`, chunk type 11); `sm_data` table 0x60 bytes, reference counted (`sm_reference`)."},
 "MenuGroup": {"what": "Container place (chunk type 5): children @0x4c linked via `next_place`, key place @0x48 (cursor target), Q15 alpha @0x44, running min corner @0x3c/0x40. `AddPlace` grows the group rect to enclose the child. Forwards SetColor/SetAlpha/SetBright/SetOwner/Attach/Detach/AllotPacket to the children; `Update` offsets children by the group position (x16) and scales alpha (`param_4 * alpha >> 15`). `GetKeyRect` returns the key place's rect translated by the group.",
   "rust": "`widget::Group`, `Widget::group_add`."},
 "MenuWindow": {"what": "Window container, the unit the game opens and closes. Children: a priority-sorted draw table (`MenuObjTable` @0x18), a list of selectable places (@0x38, linked by `MenuPlace.next`), a style decoration object (@0x3c, one of `MenuWindow{Message,Face,Note,Frame,Plain,General,Compact}` selected by `Create`'s style argument), optional `ScrollData` (@0x40, grid scrolling), `ScrollMark` (@0x44) and a `Scissor` (@0x4c). Geometry floats @0x64..0x70, clip shorts, scroll offset @0x8c/0x90, alpha Q15 @0xac, state byte @0xa8 (0 closed, 1 open, 5 sliding, 6 zoom, 7 fade).",
   "flow": "`Open(effect, frames)` / `Close(effect, frames)`: effect 0 fade (alpha lerp to/from 0x8000), 1 slide from/to above (y = -(h+100)), 2 below (y = 548), 3 left (x = -(w+100)), 4 right (x = 612), 5 zoom (scissor shrinks to the centre). `Polling` steps the animation with the frame delta, then the scroll animation (exponential approach `d*dt*0.01`, optional per-axis speed clamp, ends below 1 px), then polls children. `Finish()` snaps the animation; for closing windows it clears the render flag. Cursor navigation helpers: `GetPlace(col,row)`, `GetPlace(dir,col,row)` (nearest in a direction), `GetCornerPlace`, `MovePlace` (with wrap flags 0xb1 bit3/bit4), `SetCursor(cursor, mode)` (nearest place to the cursor's screen position), `Scroll(col,row)` / `Scroll(place)` / `Scroll(rect)`. `AllotPacket()` attaches only the places inside the visible grid window. `SetScrollMark` selects which of the four arrows show.",
   "rust": "`window::Window`, `WindowStyle`, `Effect`, `MenuRoot`.", "open": "- exact metrics of the Frame/Note/Message/Compact decorations (General's layout rule is ported in `Window::layout_deco`)"},
 "MenuWindowObject": {"what": "Abstract decoration base (vptr, owner window)."},
 "MenuWindowPlain": {"what": "Style 5: single gradient polygon (top colour 0x30,0x30,0x60 / bottom 0x20,0x20,0x40) filling the window."},
 "MenuWindowFrame": {"what": "Style 4: gradient fill (same colours as Plain) plus a `MenuFrame` outline (14 qwords) drawn around it."},
 "MenuWindowFace": {"what": "Style 2: character portrait holder: sprite record 0x13 of the common scene + a `SendOnLocal` bound to the face texture loaded through `MenuObj::sm_pFace` (`FI_%03d.TEX`)."},
 "MenuWindowNote": {"what": "Style 3: seven sprites (common scene records 0..6) forming a note/label panel."},
 "MenuWindowMessage": {"what": "Style 1: dialogue box: four sprites (records 0x14..0x17) + polygon record 0 of the common scene."},
 "MenuWindowGeneral": {"what": "Style 6: the standard menu panel: ten sprites (common scene sprite records 8..0x11 -- corners, edges, trim) and polygon record 1 as the translucent fill; `Update` re-lays the pieces from the window size: right pieces follow W' = w + rec7.priority, bottom pieces follow H' = h + rec8.priority, edge pieces stretch (the signed `priority` field of the common sprite records doubles as a pad value)."},
 "MenuWindowCompact": {"what": "Style 7: five sprites (records 0x18..0x1c) -- small compact panel."},
 "Cursor": {"what": "The selection cursor (hand/arrow). Owns a `MenuPolygon` image @0x1c, a `SendOnLocal` texture binding @0xa0, optional shadow polygon / flare trail, and follows a target with exponential smoothing. Types are indexed in a table at 0x4217a8 (stride 0x40: image size + RasterPacket). Direction (8 right-pointing .. 1 up) controls offset and a 90/180-degree rotation; `rotate` spins the image about the X axis (`angle += dt*0.5` degrees, wraps at 180).",
   "flow": "`Select(place)` converts the cursor's screen position to window-local, scrolls the window to reveal the place, then `place->IsSelected(cursor)`; `MoveCursor(dir)` uses `MenuWindow::MovePlace`; `SkipCursor(dir)` jumps a page; `Leave()` converts back to screen space and cancels the place. `SetTarget(x,y)` plays the move sound (`MenuSound::PlaySE(0)`).",
   "rust": "`cursor::Cursor`, `PlaceRef`."},
 "ScrollMark": {"what": "Four blinking arrows at the window edges telling which directions have more content (`SetMark(mask)`: 1 up, 2 down, 4 left, 8 right; `SetArea`)."},
 "KeyWait": {"what": "Blinking 'press button' marker (down arrow icon) shown by `primWin::addKeyWait`."},
 "MenuFlare": {"what": "Additive light-trail attached to the cursor (shadow type 2): ring of fading sprites following the cursor path (`SetOffset`, `ClearAfter`, `Polling`)."},
 "MenuFrame": {"what": "Outline frame primitive for `MenuWindowFrame` (14-qword packet)."},
 "MenuRegister": {"what": "Draws a numeric register (digits via sprite sheet) -- `SetRegister(index, value, flags)`/`Update`."},
 "MenuBar": {"what": "Gauge bar (HP/MP style): `SetBar`, `SetRange(min,max)`, `Round`."},
 "MenuIcon": {"what": "Inline icon object for message text (button glyph), `Create(char)`, `SetOwner`, `Finish`."},
 "MenuTexture": {"what": "Texture upload wrapper (`Create(buf, psm, w?, h?)`, `OrderFile`) used by the common scene and GameOver; owns a `RasterPacket`."},
 "MenuSound": {"what": "Menu SE player. Loads an SDH header (`ReadSDH`), `FindSDH(id)`, `PlaySE(seId, ch, vol, SeParam*)`; created by `MenuObj::CreateField`. `Polling` frees finished voices. `Cursor::SetTarget` plays SE 0."},
 "MenuModel": {"what": "3D model shown inside menus (character viewer in equip/status): model + motion player; `Order`, `CalcMatrix`, `SetAngle`, alpha/colour override, callbacks for translation/event/motion end."},
 "MenuModelPack": {"what": "A model with its motion set and effect models; `SetMotion`, `SetAction`, `AddTime`, `BootEffect`, `FindMotion(MenuMotionConnect*, name)`."},
 "MenuModelManeger": {"what": "Loader/cache for menu models (`Create(path)`, `OrderFile`, `ReadFile`, `Polling`, `Access`, `Reset`); files `MENU/DAT/*.MMD` (model), `*.MTD`, `*.MED` (effect/motion data)."},
 "MenuEffectModel": {"what": "Effect model instance used by `MenuModelPack` (`Order`, `Release`, `SetTest`)."},
 "MenuModelPrim": {"what": "VIF1Prim adapter that emits a `MenuModel`'s packets into the menu OT."},
 "MenuCapture": {"what": "Screen capture used as a blurred/frozen background under menus (`Capture(x,y,w,h,psm)`, `Release`, `getPacket`)."},
 "MenuRender": {"what": "The VIF1Prim layer (World OT layer 13) that draws all menu windows: `Create` builds the 0xa0-byte GIF header packets (ALPHA/TEST/TEX registers), `getPacket` (called once per frame) runs `UpdateTimer`, `TraceUpdate(0x7000, 0x7200, 0x8000)` (GS centre offset for the 512x448 frame, alpha 1.0), then `TraceConnect`. `Entry(layer)` registers with `CPoller(app+0x54)` and `World::AddOT`.",
   "rust": "`window::MenuRoot::{update_timer, poll, draw}`."},
 "MenuPacket": {"what": "Double-buffered GS packet memory (quadwords): `CreatePacket(n)` allocates 2n qwords, `SetPacket(n, a, b)` borrows memory, `ConnectPacket(prev)` writes the DMA tag chaining this packet after `prev` and returns the new tail. Not needed in the port (replaced by immediate draw commands)."},
 "SendOnLocal": {"what": "Texture register block (TEX0/CLAMP/... for a RasterPacket + ClutRaster) sent in front of sprites that sample it; `Create(RasterPacket*, ClutRaster*, ...)`, `UpdatePacket`, `GetTex0`."},
 "Font": {"what": "Menu font table (global `Font::CreateFont(n, bytes)`, `GetFontCode(sjis)`) -- glyph metric lookup used by `FontItem`."},
 "MenuScene": {"what": "A loaded `.MSD` scene. `OrderFile(path, menu)` queues a DVD read (`pDataPath + path`); the callback `ReadScene` relocates pointers (`MenuDataTable::Convert`) and `Initialize(data, buf)` indexes the chunk list into `tab_* @0x24..0x54` by chunk type, then the virtual `GetReady()` (+0x14) builds the widgets. `SetData(index, widget)` overloads fill a freshly created widget from record `index` (FontDraw 0x10, Cursor 0xc, Window 0x1c, Group 0x18, Sprite 0x20, Polygon 0x3c, Text 0x1c, Message 0x20, Font 0x1c, FontItalic 0x18 byte records). `FindAttachFile(id)` finds an embedded blob. `MoveVertical(keys)` maps pad bits to `MoveCursor/SkipCursor` on the scene cursor.",
   "rust": "`scene::Scene`, `msd::Msd`, `SceneLogic`."},
 "Menu": {"what": "Scene manager polled by `CPoller` (priority 0x80). Holds the scene list (+0x38, linked through the scene's `next`), the active scene (+0x34) and the key word (+0x48 = `(trigger & 0xff0f) | (repeat & 0xf0)`). `Run()` calls the active scene's virtual `Run` (+0x1c) and, if the scene is 'created' (+0x23 bit4), `GetReady`. `Active(id)`, `Ready()`, `Shutdown()/Restore()` put all other scenes to sleep. `DestroyList()` deletes every scene.",
   "rust": "`scene::Menu`."},
 "MenuDataTable": {"what": "Loader for a standalone table file (`.MDT`, e.g. `MENU/DAT/SAVELIST.MDT` used by `SaveMenuSection`'s place-name table): `Order(path)` -> `ReadDataFunc` -> `Create(data, buf)` which relocates with mode 1 (pointers relative to their chunk). `Find(type)` walks the chunk list. `Convert(data, mode)` is the relocation pass shared with scenes."},
 "MenuCommon": {"what": "The common scene (`COMMON/CMNMENU.DAT`): creates font 0 and 14 `MenuTexture`s from embedded attach files (window skin, icons, digits, cursors). `SetIcon(index, sprite)` selects an icon from the 8-column icon atlas by setting the sprite's UV rect.", "rust": "records via `Scene`."},
 "MenuFieldData": {"what": "Scene holder for the in-field command menu data (MENU.PKB `DAT/CMDMENU.MSD`): relocates attach tables 4..10 with `Convert`; copies its buffer into the field memory heap (`FldMemory::FldAlloc`) when available (`GetRealHeap`)."},
 "MenuFieldStationed": {"what": "Field menu resident scene (`DAT/MFIELD.MSD`); `GetReady` creates font 1."},
 "SaveDataSection": {"what": "Base class of the three save sections. Holds a pointer to the section header+data inside the `SaveData` heap (+8) and a link to the next section (+4). `CreateSection(name4, size, version)` carves space in the heap (`SaveData::OrderSection`) and writes the 0x10-byte section header; virtuals: +0x0c `SetDefault`, +0x10 `SetSection(hdr, data)` (load), +0x14 `CheckVersion(u16)`, +0x18 `FlushData` (before save). `GetSection()` returns the data pointer (hdr+0x10).", "rust": "`save::SectionHdr`, `RawSection`."},
 "SaveData": {"what": "The save container object (global at 0x00421e70, `CPolObj` registered with the poller at priority 0x80 while a device is open). Owns the section list (+0x18), the heap pointer (+0x1c = fixed EE RAM 0x00100100), the open device (+0x20) and a tiny command state machine: state@0x24 (0 closed, 1 busy, 2 ready, 3 error), `last_op@0x28`, `pending_op@0x29` (1 open, 2 close, 3 create-system, 4 get-status, 5 save, 6 load, 7 delete, 8 format), slot@0x2b. `Open(kind)` allocates `SaveDeviceMC` (0x3fc bytes) or `SaveDeviceHDD` (0x3f8), calls `Device::Open`. `Polling` drives `Device::Sync()`; results -1 error, -2 skip, 1 busy. The header written to the file is built by the ctor: checksum, magic `SSH_SAVE`, hdr size 0x20, payload size, section count.", "rust": "`save::SaveFile`, `storage::SaveManager`."},
 "SaveDevice": {"what": "Abstract storage device. Constants: folder `BISLPM-00000-SH2`, slot name `SH2-%03d`, icon file `SH2.ICO` from `COMMON/` on the disc. State bytes: port@4, flags@5 (bit0 folder exists, bit1 system file valid, bit2 icon loading, bit3 icon ready, bit4 heap owned), op@6/step@7, io phase@8/10. Embeds the `SystemFile` at +0x1c. `NewHeap/DeleteHeap` allocate the read buffer; `LoadIcon` reads the .ICO from the disc; `CreateIcon` builds `icon.sys` (0x3c4 bytes: title, 3 icon file names, lighting values).", "rust": "`storage::SaveStorage` trait."},
 "SaveDeviceMC": {"what": "Memory-card implementation: `sceMc*` wrappers and the `Sync()` state machine (op 1..8)."},
 "SaveDeviceHDD": {"what": "PS2 HDD implementation: partition `__common`, unit `hdd0:`, `sm_appPfs`; same ops over pfs."},
 "SystemFile": {"what": "In-memory image of the `BISLPM-00000-SH2` system file (see save_format.md section 7): 0x100 byte common block (EE RAM 0x100000), 15 x 0x60 byte slot summaries. `Create` builds an empty one (all slots 0xff), `SetData` validates `SYSH` and copies, `StoreCommon/FlushCommon` copy the common block, `SetCurrentSlot` picks the first used slot.", "rust": "`save::SystemFile`, `SlotInfo`."},
 "BtlSaveSec": {"what": "`BTL0` section = the party database: 12 character records, bag(s), skills, fusion monsters, Yoahism counter. Also the battle-side accessor class (`GetPCParam/SetPCParam/AddPCParam`, `GetReal*` equipment-adjusted stats, level/EXP logic, `SetSceneInit(scenario)` which resets the whole block for a story part from `RegDat 0x26+n` (starting PC) and `0x3f` (starting items) tables, `DemoInitPCParam` for the attract battles). Global pointers: `ourBtlSaveSec` (object), `ourBtlSaveDat` (section data).", "rust": "`save::BtlSave`, `save::PcRec`, `btlsave` module (level/EXP/Yoahism)."},
 "CFieldSaveData": {"what": "`FLDa` section = 16-byte-unit chunk database for field state (GS, RG script registers, TR treasure bits, WM world map, NP npc encounter nibbles). `AddChunk(tag2, units, flag)`, `FindChunk(tag2)`, `SetSection` (load: copies header+data and recounts units), `SetDefault`. Global `sys` @sys__14CFieldSaveData.", "rust": "`save::FieldSave`."},
 "SaveMenuSection": {"what": "`MENU` section: play time, cash, 5 party sets, pad assignment, option bits (vibration, sound out, text speed, window colours), brightness. Static `sm_pSubstance` points at the object; `+0xc` is the data pointer; `+0x10` embeds a `MenuDataTable` that holds the place-name table (`SAVELIST.MDT`, type 0x2d rows (name ptr, map id)). `Update()` applies the options every frame: `CApp::SetBright(v*0.03+0.7)`, `Sdrv::SetMode`, `CPad::SetAssign`, `CVibeMan::SetMode`.", "rust": "`save::MenuSave`, `PartySet`."},
 "dataAccess": {"what": "Save / Load / device-check screen (see dataAccess.md). Created by the field save point / command menu (mode 0), `GameOverScene::SelectLoad` (mode 1) and the title (mode 2 initial check). Callback `cb(event, arg)` at +0x24/+0x28.", "rust": "`dataaccess::DataAccess`."},
 "deviceChecker": {"what": "Probes the three devices: `checkDeviceAll` -> `mCheckAll` (opens each, reads the system file), `checkPollMC` / `finishPollMC` poll card hot-plug (`mPollMC`), queries `getActiveDeviceNum`, `getSavedDeviceNum`, `getFreeDeviceNum`, `isOnlyHDD`, `isHDD`, `isChangeStatus`, `closeDevice`.", "rust": "`dataaccess::check_all`."},
 "dispSaveFile": {"what": "One slot panel on the save list (3 visible): shows leader name, level, play time (`dispTime`), cash (`dispCash`), location, party faces (model numbers -> `FI_%03d` portraits); `setMove/move` animate the list scroll."},
 "dispTime": {"what": "Play-time display: 10 digit sprites `HHHH:MM:SS`; adds 16 per frame while running; digit 0xb = colon, 0xc = blank (leading zeros suppressed)."},
 "dispCash": {"what": "Cash display: up to 9 digits with thousands separators (digit 10) and blank padding (12)."},
 "openingMessage": {"what": "Title screen driver (switch on state @0xe0, see title_flow.md). Created by `CDMYStage::Start`; owns the fader window, title sprites (6 `prim2D`), menu window + cursor, music/sound objects, the `dataAccess` and the attract battle.", "rust": "`title::OpeningMessage`."},
 "openingBattleDemo": {"what": "Attract-mode battle: builds a party in the MENU section, configures `BtlSocket` (SetPC, SetMonsterSet from RegDat 0x2f, BGM) and lets BATTLE.BIN run an AI-controlled fight; cycles three setups (`m_mons`).", "rust": "`title::OpeningBattleDemo`, `DEMO_BATTLES`."},
 "GameOver": {"what": "`Menu` subclass created by `SSHSys::PollingApi` on state 0x30; creates its `GameOverScene` (`MENU/MSD/GAMEOVER.MSD`) and a default `GsxCamera` if none exists. `ReceiveEvent(event, menu)` is the `dataAccess` callback (4 finished, 5 loaded).", "rust": "`gameover::GameOverScene`."},
 "GameOverScene": {"what": "State machine (pointer-to-member at +0x58): GetReady, ReadData, Realize, ExitRealize, SelectLoad, ExitSelectLoad. Image index from MENU `0x29c` (random among `0x29e` mask bits if negative).", "rust": "`gameover::GameOverScene`."},
 "GameOverSelect": {"what": "Holder object of the Load?/Yes/No question window, cursor, FontDraw and three MenuText."},
 "GameOverRealize": {"what": "Holder object of the illustration: window, MenuTexture, SendOnLocal, MenuSprite."},
 "ComboTrial": {"what": "Combo judgement-ring trial display (listed in section F's scope but it is a `JRing`-adjacent VIF1Prim; `MakePacket`/`Polling` draw ring markers) -- constructed by `JRing::Sequence`.", "open": "- belongs with section D (JRing); only decompiled here"},
}
